using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
namespace JingYue {
 public partial class MainWindow {
  List<ReadingUnit> units=new List<ReadingUnit>();ReadingPage page;Stack<ReadingCursor> pageHistory=new Stack<ReadingCursor>();
  StackPanel pageBar;TextBlock pageLabel;Button previousPage,nextPage,scrollMode,pagesMode;DateTime lastWheel=DateTime.MinValue;bool pageLayoutPending;
  bool Pages {get{return settings.ReadingMode=="pages";}}
  void BuildReadingControls(Grid content){content.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});content.RowDefinitions.Add(new RowDefinition());content.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var bar=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(24,8,24,0)};bar.Children.Add(new TextBlock{Text="阅读方式",VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,12,0),Opacity=.65});scrollMode=Btn("上下滚动",()=>SetReadingMode(false));pagesMode=Btn("左右翻页",()=>SetReadingMode(true));bar.Children.Add(scrollMode);bar.Children.Add(pagesMode);content.Children.Add(bar);pageBar=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,0,0,8)};previousPage=Btn("← 上一页",()=>ChangePage(-1));nextPage=Btn("下一页 →",()=>ChangePage(1));pageLabel=new TextBlock{Margin=new Thickness(18,0,18,0),VerticalAlignment=VerticalAlignment.Center};pageBar.Children.Add(previousPage);pageBar.Children.Add(pageLabel);pageBar.Children.Add(nextPage);Grid.SetRow(pageBar,2);content.Children.Add(pageBar);ApplyModeVisuals();}
  void ApplyModeVisuals(){if(pageBar==null)return;pageBar.Visibility=Pages?Visibility.Visible:Visibility.Collapsed;scrollMode.SetResourceReference(Control.BackgroundProperty,Pages?"Panel":"SearchFill");pagesMode.SetResourceReference(Control.BackgroundProperty,Pages?"SearchFill":"Panel");if(reader!=null){reader.Padding=Pages?new Thickness(24,10,24,10):new Thickness(24,24,24,100);reader.SetValue(ScrollViewer.VerticalScrollBarVisibilityProperty,Pages?ScrollBarVisibility.Disabled:ScrollBarVisibility.Auto);}}
  void SetReadingMode(bool pages){if(loading||Pages==pages)return;CapturePosition();settings.ReadingMode=pages?"pages":"scroll";pageHistory.Clear();ApplyModeVisuals();root.UpdateLayout();if(current!=null&&units.Count>0){int target=ReadingUnit.Find(units,current.Position,current.VisualPart);restoringPosition=true;if(Pages)ShowPage(new ReadingCursor(target,current.PageCharacter),0);else{reader.ItemsSource=units;reader.UpdateLayout();ScrollToUnit(target,current.ParagraphOffset);}restoringPosition=false;UpdateReadingProgress();}Save();}
  PageEngine Engine(){double width=reader.Tag is double?(double)reader.Tag:700;return new PageEngine(units,width,Math.Max(120,reader.ActualHeight-reader.Padding.Top-reader.Padding.Bottom-3),settings.FontSize,settings.Line,settings.Font);}
  void ShowPage(ReadingCursor cursor,int direction){if(units.Count==0)return;cursor.Unit=Math.Max(0,Math.Min(cursor.Unit,units.Count-1));if(units[cursor.Unit].Paragraph==null)cursor.Character=0;page=Engine().Build(cursor);reader.ItemsSource=page.Pieces;reader.SelectedIndex=-1;var sc=FindVisual<ScrollViewer>(reader);if(sc!=null)sc.ScrollToTop();previousPage.IsEnabled=page.Start.Unit>0||page.Start.Character>0;nextPage.IsEnabled=!page.End;if(direction!=0){var transform=new TranslateTransform();reader.RenderTransform=transform;transform.BeginAnimation(TranslateTransform.XProperty,new System.Windows.Media.Animation.DoubleAnimation(direction>0?22:-22,0,TimeSpan.FromMilliseconds(140)));}UpdateReadingProgress();}
  void ChangePage(int direction){if(loading||!Pages||document==null||page==null||layout.Visibility!=Visibility.Visible)return;if(direction>0){if(page.End)return;pageHistory.Push(page.Start);ShowPage(page.Next,1);}else{var prior=pageHistory.Count>0?pageHistory.Pop():Engine().Previous(page.Start);if(prior.Equals(page.Start))return;ShowPage(prior,-1);}CapturePosition();Save();}
  void PageWheel(object sender,MouseWheelEventArgs e){if(!Pages)return;e.Handled=true;if((DateTime.UtcNow-lastWheel).TotalMilliseconds<170)return;lastWheel=DateTime.UtcNow;ChangePage(e.Delta<0?1:-1);}
  bool PagingKey(KeyEventArgs e){if(!Pages||layout.Visibility!=Visibility.Visible||Keyboard.FocusedElement is TextBox||Keyboard.Modifiers!=ModifierKeys.None)return false;if(e.Key==Key.Left||e.Key==Key.PageUp){ChangePage(-1);e.Handled=true;return true;}if(e.Key==Key.Right||e.Key==Key.PageDown||e.Key==Key.Space){ChangePage(1);e.Handled=true;return true;}return false;}
  void RefreshPageLayout(){if(Pages&&page!=null&&!loading&&!restoringPosition&&layout.Visibility==Visibility.Visible){pageHistory.Clear();ShowPage(page.Start,0);}}
  void ReadingSizeChanged(object sender,SizeChangedEventArgs e){if(pageLayoutPending)return;pageLayoutPending=true;Dispatcher.BeginInvoke(new Action(()=>{pageLayoutPending=false;RefreshPageLayout();}),DispatcherPriority.Loaded);}
  int TopUnit(){int best=Int32.MaxValue;double top=ViewTop();var panel=FindVisual<VirtualizingStackPanel>(reader);if(panel!=null)foreach(UIElement child in panel.Children){var item=child as ListBoxItem;if(item==null)continue;var u=item.DataContext as ReadingUnit;if(u==null)continue;try{if(item.TransformToAncestor(reader).Transform(new Point(0,item.ActualHeight)).Y>top+1)best=Math.Min(best,u.Index);}catch{}}return best==Int32.MaxValue?(current==null?0:ReadingUnit.Find(units,current.Position,current.VisualPart)):best;}
  double UnitFraction(int index){if(index<0||index>=units.Count)return 0;var item=reader.ItemContainerGenerator.ContainerFromItem(units[index]) as ListBoxItem;if(item==null||item.ActualHeight<=0)return 0;double y=item.TransformToAncestor(reader).Transform(new Point()).Y;return Math.Max(0,Math.Min(.999,(ViewTop()-y)/item.ActualHeight));}
  void StoreCursor(ReadingCursor cursor,double fraction){if(current==null||units.Count==0)return;int index=Math.Max(0,Math.Min(cursor.Unit,units.Count-1));var u=units[index];current.Position=u.LogicalIndex;current.VisualPart=u.Part;current.ParagraphOffset=fraction;current.PageCharacter=cursor.Character;current.LastReadUtc=DateTime.UtcNow.ToString("o");var chapter=document.Chapters.LastOrDefault(c=>c.Index<=u.LogicalIndex);current.LastChapter=chapter==null?null:chapter.Text;}
  void CaptureReadingPosition(){if(current==null||loading||restoringPosition||layout.Visibility!=Visibility.Visible||units.Count==0)return;if(Pages&&page!=null){double fraction=units[page.Start.Unit].Paragraph==null?0:(double)page.Start.Character/Math.Max(1,units[page.Start.Unit].Paragraph.Text.Length);StoreCursor(page.Start,fraction);}else{int index=TopUnit();double fraction=UnitFraction(index);int character=units[index].Paragraph==null?0:PageEngine.SafeBoundary(units[index].Paragraph.Text,(int)(units[index].Paragraph.Text.Length*fraction));StoreCursor(new ReadingCursor(index,character),fraction);}}
  void UpdateReadingProgress(){if(document==null||units.Count==0||current==null)return;int index=Pages&&page!=null?page.Start.Unit:TopUnit();double fraction=Pages&&page!=null?(units[index].Paragraph==null?0:(double)page.Start.Character/Math.Max(1,units[index].Paragraph.Text.Length)):UnitFraction(index);double value=(index+fraction)/units.Count;var sc=FindVisual<ScrollViewer>(reader);if(Pages&&page!=null&&page.End||!Pages&&sc!=null&&sc.ViewportHeight>0&&sc.ScrollableHeight-sc.VerticalOffset<1)value=1;current.Progress=Math.Max(0,Math.Min(1,value));progress.Text=String.Format("{0:0.0}% · {1}",current.Progress*100,Pages?"左右翻页（滚轮 / ← →）":"上下滚动");if(pageLabel!=null)pageLabel.Text=String.Format("{0:0.0}%",current.Progress*100);}
  void ReadingScrolled(){if(loading||restoringPosition||document==null||layout.Visibility!=Visibility.Visible)return;UpdateReadingProgress();if(!Pages){saveTimer.Stop();saveTimer.Start();}}
  void ScrollToUnit(int index,double fraction){if(units.Count==0)return;index=Math.Max(0,Math.Min(index,units.Count-1));reader.ScrollIntoView(units[index]);reader.SelectedIndex=-1;reader.UpdateLayout();var item=reader.ItemContainerGenerator.ContainerFromItem(units[index]) as ListBoxItem;var sc=FindVisual<ScrollViewer>(reader);if(item!=null&&sc!=null){double y=item.TransformToAncestor(reader).Transform(new Point()).Y;sc.ScrollToVerticalOffset(Math.Max(0,sc.VerticalOffset+y-ViewTop()+fraction*item.ActualHeight));reader.UpdateLayout();}}
  void JumpLogical(int logical){if(document==null||units.Count==0)return;int index=ReadingUnit.Find(units,logical,0);if(Pages){pageHistory.Clear();ShowPage(new ReadingCursor(index,0),0);}else ScrollToUnit(index,0);StoreCursor(new ReadingCursor(index,0),0);UpdateReadingProgress();}
 }
}
